import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
export async function runMotionImageCropSmoke(page,templates){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()})),dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-crop-'));
 const wide=path.join(dir,'Horizontal.svg'),tall=path.join(dir,'Vertical.svg');for(const [file,w,h] of [[wide,1200,200],[tall,200,1200]])await fs.writeFile(file,'<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'">'+['#ff0000','#00ff00','#0000ff'].map((color,i)=>'<rect x="'+(w>h?i*400:0)+'" y="'+(h>w?i*400:0)+'" width="'+(w>h?400:200)+'" height="'+(h>w?400:200)+'" fill="'+color+'"/>').join('')+'</svg>');
 let revision=0;
 async function ready(count){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('[data-nw-stream-slot]').length===count&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&d.querySelector('[data-motion-canvas]')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function change(selector,value,count){const mark='crop-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.cropOld=mark;n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelector('[data-nw-stream-slot]')&&d.body.dataset.cropOld!==mark;},{},mark);await ready(count);}
 async function sample(id,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{id,gid})=>{const d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(.5);const n=d.querySelector('[data-id="'+id+'"]'),c=n.querySelector('canvas');if(c.classList.contains('nw-stack-card')||c.classList.contains('nw-toss-card')){let found=false;for(let i=0;i<40;i++){if(i)f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(i/40);const s=n.__nwMotionSurface,clip=n.__nwMotionClip;if(+c.style.opacity<.9||s.length<4)continue;const p=s.reduce((a,v)=>({x:a.x+v.x/s.length,y:a.y+v.y/s.length}),{x:0,y:0});if(p.x>clip.left+2&&p.x<clip.left+clip.width-2&&p.y>clip.top+2&&p.y<clip.top+clip.height-2){found=true;break;}}if(!found)throw new Error('No visible sequence image center for crop sampling');}if(+c.style.opacity<.9)for(let i=0;i<20;i++){f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(i/20);if(+c.style.opacity>=.9)break;}if(n.__nwMotionInstances){const host=n.offsetParent,shared=host.querySelector('.nw-ticker-surface,.nw-carousel-surface,.nw-focus-surface');for(let k=0;k<40;k++){if(k)f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(k/40);for(const tile of n.__nwMotionInstances){const p=tile.polygon.reduce((a,v)=>({x:a.x+v.x/4,y:a.y+v.y/4}),{x:0,y:0});if(p.x<10||p.y<10||p.x>host.clientWidth-10||p.y>host.clientHeight-10)continue;if(c.classList.contains('nw-focus-card')){const inside=(poly,x,y)=>{let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++)if((poly[i].y>y)!==(poly[j].y>y)&&x<(poly[j].x-poly[i].x)*(y-poly[i].y)/(poly[j].y-poly[i].y)+poly[i].x)hit=!hit;return hit;};const clip=n.__nwMotionClip;if(p.x<=clip.left+2||p.y<=clip.top+2||p.x>=clip.left+clip.width-2||p.y>=clip.top+clip.height-2||Array.from(host.querySelectorAll('[data-nw-stream-slot]')).some(other=>other.__nwMotionInstances.some(t=>t.depth>tile.depth&&inside(t.polygon,p.x,p.y))))continue;}const pixel=Array.from(shared.getContext('2d').getImageData(Math.floor(p.x/host.clientWidth*shared.width),Math.floor(p.y/host.clientHeight*shared.height),1,1).data);if(pixel[3]>220)return pixel;}}throw new Error('No fully visible ticker copy for crop sampling');}const s=n.__nwMotionSurface;const p=s.reduce((a,v)=>({x:a.x+v.x/s.length,y:a.y+v.y/s.length}),{x:0,y:0}),x=(p.x-parseFloat(n.style.left))/parseFloat(n.style.width)*c.width,y=(p.y-parseFloat(n.style.top))/parseFloat(n.style.height)*c.height;return Array.from(c.getContext('2d').getImageData(Math.floor(x),Math.floor(y),1,1).data);},{id,gid});}
 async function color(id,expected,selector,gid){const p=await sample(id,selector,gid);assert.ok(p[3]>15,JSON.stringify(p));for(let i=0;i<3;i++)assert.ok(Math.abs(p[i]-expected[i])<6,JSON.stringify({pixel:p,expected}));}
 async function upload(id,file,count){const index=await page.$eval('[data-motion-content-panel] .crow:not([hidden]) [data-motion-upload]',n=>n.dataset.motionUpload);await (await page.$('[data-motion-upload="'+index+'"]')).uploadFile(file);await page.waitForFunction(({id,w})=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"] img')?.naturalWidth===w,{},{id,w:file===wide?1200:200});await ready(count);}
 try{
  for(const template of templates||['showcase-stream','iso-orbit','pop-grid','center-stage','orbit-bloom','ticker-tilt','ticker-loop','carousel-flow','stack-slide','iso-focus-sequence','card-toss']){
   const count=template==='iso-orbit'?9:template==='pop-grid'?6:template==='center-stage'?3:template==='carousel-flow'?5:template==='stack-slide'?4:template==='iso-focus-sequence'?10:template==='card-toss'?8:template==='cascade-drop'?4:12;
   await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY)}));
   await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="'+template+'"]');await ready(count);assert.equal(await page.$eval('[data-motion-image-focus-panel]',n=>n.hidden),true);const id=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].set(.5);return Array.from(d.querySelectorAll('[data-nw-stream-slot]')).filter(n=>n.__nwMotionVisible&&+n.querySelector('canvas').style.opacity>.9).sort((a,b)=>+b.dataset.nwStreamDepth-+a.dataset.nwStreamDepth)[0].dataset.id;});await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+id+'"]');assert.equal(await page.$eval('[data-motion-image-focus="x"]',n=>n.value),'50');assert.equal(await page.$eval('[data-motion-image-focus="y"]',n=>n.value),'50');await upload(id,wide,count);await color(id,[0,255,0]);await change('[data-motion-image-focus="x"]','0',count);await color(id,[255,0,0]);await change('[data-motion-image-focus="x"]','100',count);await color(id,[0,0,255]);const targetPosition=await page.$eval('[data-motion-stream-order]',(n,count)=>+n.value===count?'1':String(count),count);await change('[data-motion-stream-order]',targetPosition,count);await color(id,[0,0,255]);assert.equal(await page.$eval('[data-motion-image-focus="x"]',n=>n.value),'100');
   // Replacing the source preserves its authored focus; vertical crop has its own axis.
   await upload(id,tall,count);await color(id,[0,255,0]);await change('[data-motion-image-focus="y"]','0',count);await color(id,[255,0,0]);await change('[data-motion-image-focus="y"]','100',count);await color(id,[0,0,255]);const resetMark='crop-reset-'+(++revision);await page.$eval('.nw-motion-dialog iframe',(f,mark)=>f.contentDocument.body.dataset.cropOld=mark,resetMark);await page.click('[data-motion-image-focus-reset]');await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.cropOld!==mark&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id];},{},resetMark);await ready(count);await color(id,[0,255,0]);await change('[data-motion-image-focus="y"]','100',count);
   await page.$eval('[data-motion-image-focus="y"]',n=>{n.value='';n.dispatchEvent(new Event('change',{bubbles:true}));});assert.equal(await page.$eval('[data-motion-image-focus="y"]',n=>n.value),'100');await change('[data-motion-config="source"]','scroll',count);await color(id,[0,0,255]);assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi encuadre');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.deepEqual(saved.elements.find(e=>e.id===id).nwStreamFocus,{x:50,y:100});await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(id=>({gid:sec().elements.find(e=>e.nwMotionInstance).id,project:JSON.stringify(project),element:sec().elements.find(e=>e.id===id)}),id);assert.deepEqual(inserted.element.nwStreamFocus,{x:50,y:100});
   await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready(count);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+id+'"]');assert.equal(await page.$eval('[data-motion-image-focus="y"]',n=>n.value),'100');await color(id,[0,0,255]);await change('[data-motion-image-focus="y"]','0',count);await color(id,[255,0,0]);if(template==='pop-grid'){await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/image-crop-desktop.png'});await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.$eval('[data-motion-image-focus-panel]',n=>n.scrollIntoView({block:'nearest'}));assert.equal(await page.$eval('[data-motion-image-focus="y"]',n=>n.getClientRects().length>0),true);await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/image-crop-mobile.png'});await page.setViewport(viewport);}await page.click('[data-motion-save]');const edited=await page.evaluate(()=>JSON.stringify(project));await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),edited);assert.deepEqual(await page.evaluate(id=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===id).nwStreamFocus,id),{x:50,y:0});
   await page.evaluate(()=>{const f=document.createElement('iframe');f.id='crop-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(({id,gid})=>{const f=document.querySelector('#crop-export'),img=f?.contentDocument?.querySelector('[data-id="'+id+'"] img');return img?.complete&&img.naturalWidth===200&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[gid];},{},{id,gid:inserted.gid});await color(id,[255,0,0],'#crop-export',inserted.gid);await page.evaluate(()=>document.querySelector('#crop-export').remove());await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready(count);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+id+'"]');await change('[data-motion-image-focus="y"]','100',count);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),edited);
  }
  console.log('Encuadre Motion Lab: píxeles reales en extremos horizontal/vertical y centro, imagen reemplazada y reordenada, borradores, Biblioteca, instancia reeditable, guardar/cancelar/historial/JSON/HTML, Scroll y Loop, escritorio y móvil en '+(templates?templates.join(', '):'Stream/Iso/Pop/Stage/Orbit Bloom/Ticker Tilt/Ticker Loop/Carousel Flow/Stack Slide/Iso Focus/Card Toss')+' OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/image-crop-failure.png'}).catch(()=>{});throw error;}finally{await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#crop-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});}
}
